// TestContainersBuilderWithMapEntries pins the merging setter.
func TestContainersBuilderWithMapEntries(t *testing.T) {
	t.Parallel()

	t.Run("keeps entries it was not given", func(t *testing.T) {
		t.Parallel()
		// Merging is the whole difference from the replacing setter; one that
		// discarded would leave the two indistinguishable.
		var k string
		var v string
		got := domaintest.NewContainers().WithMapEntry(k, v).
			WithMapEntries(map[string]string{}).Build()
		testkit.Equal(t, len(got.Map), 1, "merging keeps what was there")
	})

	t.Run("allocates Map when it merges into nothing", func(t *testing.T) {
		t.Parallel()
		// Merging into a nil map has to allocate like the single-entry setter
		// does, or the first caller to reach for it panics.
		var k string
		var v string
		got := domaintest.NewContainers().WithMapEntries(map[string]string{k: v}).Build()
		testkit.Equal(t, len(got.Map), 1, "merging allocates on first use")
	})
}

